#[cfg(test)]
mod metadata_meter {
    use super::*;
    use crate::executor_allocation_meter as meter;
    #[test]
    fn requests() {
        let pool = Budget::new(8 * 1024 * 1024, 0);
        let limits = Limits { remote: Some(Remote { program: "ssh".into(), host: "host".repeat(1000),
            user: Some("user".repeat(200)), port: Some(22), identity: Some("identity".repeat(200)), jump: Some("jump".repeat(200)) }), ..Limits::default() };
        let entry = Entry { path: "file".into(), label: "file".repeat(1000), index: b'M', worktree: b' ', source: None };
        let path = Path::new("/repository");
        let message = "commit".repeat(600);
        let denied = Budget::new(0, 0);
        meter::start();
        let _ = pool.snapshot();
        let _ = denied.snapshot();
        let budget_lazy = meter::stop();
        eprintln!("METADATA_SETUP parent_budget_lazy allocations={} live={} peak={}", budget_lazy.allocations, budget_lazy.live, budget_lazy.peak);
        meter::start();
        assert!(matches!(WriteRequest::from_source(1, 1, path, WriteSource::Commit { message: &message }, &limits, &denied), Err(Error::Budget)));
        let refused = meter::peek();
        assert_eq!(refused.allocations, 0);
        let requests = (
            StatusRequest::new(1, 1, path, &limits, Some("2.50"), &pool).unwrap(),
            LogRequest::new(1, 1, path, Some(OsStr::new("a123")), &limits, &pool).unwrap(),
            BranchRequest::new(1, 1, path, &limits, &pool).unwrap(),
            DiffRequest::new(1, 1, path, &entry, false, &limits, &pool).unwrap(),
            WriteRequest::from_source(1, 1, path, WriteSource::Commit { message: &message }, &limits, &pool).unwrap(),
        );
        let retained = meter::peek();
        let held = pool.snapshot().used;
        let peak = pool.snapshot().peak;
        assert!(retained.live as usize <= held);
        assert!(retained.peak as usize <= peak);
        drop(requests);
        let final_counts = meter::stop();
        assert_eq!(final_counts.live, 0);
        assert_eq!(pool.snapshot().used, 0);
        eprintln!("METADATA_ALLOC requests retained={} peak={} held={} reserved_peak={} denied_allocations={} final={}", retained.live, retained.peak, held, peak, refused.allocations, final_counts.live);
    }
    #[test]
    fn errors() {
        let pool = Budget::new(1024 * 1024, 0);
        let denied = Budget::new(0, 0);
        let input = [0xff; 4096];
        let mut clones = Vec::with_capacity(1000);
        meter::start();
        let _ = pool.snapshot();
        let _ = denied.snapshot();
        let budget_lazy = meter::stop();
        eprintln!("METADATA_SETUP parent_budget_lazy allocations={} live={} peak={}", budget_lazy.allocations, budget_lazy.live, budget_lazy.peak);
        meter::start();
        assert!(matches!(failure_detail(&input, Some(1), &denied), Err(Error::Budget)));
        assert_eq!(meter::peek().allocations, 0);
        let error = failure_detail(&input, Some(1), &pool).unwrap();
        let retained = meter::peek();
        let held = pool.snapshot().used;
        for _ in 0..1000 { clones.push(error.clone()); }
        assert_eq!(meter::peek().allocations, retained.allocations);
        assert!(retained.live as usize <= held);
        drop(error);
        assert_eq!(pool.snapshot().used, held);
        clones.clear();
        let final_counts = meter::stop();
        assert_eq!(final_counts.live, 0);
        assert_eq!(pool.snapshot().used, 0);
        eprintln!("METADATA_ALLOC errors retained={} peak={} held={} clone_allocations=0 denied_allocations=0 final={}", retained.live, retained.peak, held, final_counts.live);
    }
}

