#[cfg(test)]
mod metadata_meter {
    use super::*;
    use crate::executor_allocation_meter as meter;
    #[test]
    fn network() {
        let mut input = b"header\nheader\neth0: 12 0 0 0 0 0 0 0 34 0 0 0 0 0 0 0\n".to_vec();
        input.resize(NET_DEV_BYTES, b' ');
        meter::start();
        assert_eq!(read_net_dev(input.as_slice()), Some((12, 34)));
        assert_eq!(read_net_dev(std::io::repeat(b'x')), None);
        let counts = meter::stop();
        assert_eq!(counts.allocations, 0);
        assert_eq!(counts.live, 0);
        eprintln!("METADATA_ALLOC network allocations=0 peak={} final={}", counts.peak, counts.live);
    }
}
